#!/usr/bin/env node
/**
 * Render the four diffusion evidence cards without a browser or a network call.
 * Run from any directory: node /path/to/repo/scripts/render-diffusion-evidence-cards.mjs
 *
 * The six measured SVGs are rasterized whole; recovery PNGs are scaled whole.
 * No scientific data is reconstructed from pixels, interpolated, or replotted.
 * Source descriptions are checked against evidence.ts before writing anything.
 *
 * Typography uses outlines of the repository's OFL-licensed EB Garamond (500)
 * and Source Sans 3 (400). Baking the outlines avoids platform-dependent
 * WOFF2/fontconfig fallback in sharp. The compressed data below contains only
 * font geometry, never measurements. Its source hashes are checked each run.
 * Outlines were extracted with FontTools 4.63.0: TTFont, instantiateVariableFont,
 * SVGPathPen (integer font units), and BoundsPen. Each glyph stores its advance,
 * SVG path, and ink bounds. Normal rendering needs only Node, esbuild and sharp.
 */
import assert from 'node:assert/strict'
import { createHash } from 'node:crypto'
import { mkdir, readFile, writeFile } from 'node:fs/promises'
import { dirname, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'
import { runInNewContext } from 'node:vm'
import { inflateSync } from 'node:zlib'
import { transform } from 'esbuild'
import sharp from 'sharp'

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..')
const OUTPUT = resolve(ROOT, 'public/blog-assets/diffusion/share')
const WIDTH = 1200
const HEIGHT = 630
const PAPER = '#f5f1e8'
const INK = '#292c29'
const MUTED = '#64685f'
const LINE = '#d7d7cd'
const FOOTER = 'Continual Learning Diffusion Models · Zekun Wang'
const BENCHMARK_IDS = ['iclr-imagenet1k', 'trust-imagenet500', 'trust-cw10']
const PANEL_IDS = ['imagenet500', 'cw10']
const FONT_OUTLINES = {
  "serif": {
    "source": "public/fonts/typography/eb-garamond-normal-latin.woff2",
    "weight": 500,
    "sha256": "68fd4b247dde89984ee835d99953d235e4927be2b1b732ad81173b519869cee8",
    "data": ""
  },
  "sans": {
    "source": "public/fonts/typography/source-sans-3-normal-latin.woff2",
    "weight": 400,
    "sha256": "ac057a5593cbe3df0d2585da5dd5f33b8efa84aa30550c710fe061b37fc5c54b",
    "data": ""
  }
}

function xml(value) {
  return String(value).replace(/[&<>"']/g, character => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&apos;',
  })[character])
}

async function loadData(relativePath) {
  const source = await readFile(resolve(ROOT, relativePath), 'utf8')
  const compiled = await transform(source, {
    loader: 'ts', format: 'cjs', target: 'node20', sourcefile: relativePath,
  })
  const module = { exports: {} }
  runInNewContext(compiled.code, { module, exports: module.exports }, {
    filename: relativePath, timeout: 1000,
  })
  return module.exports
}

async function loadFonts() {
  const entries = await Promise.all(Object.entries(FONT_OUTLINES).map(async ([name, record]) => {
    const source = await readFile(resolve(ROOT, record.source))
    assert.equal(
      createHash('sha256').update(source).digest('hex'), record.sha256,
      `${record.source} changed; refresh the baked font outlines before rendering.`,
    )
    return [name, JSON.parse(inflateSync(Buffer.from(record.data, 'base64')).toString())]
  }))
  return Object.fromEntries(entries)
}

function textGeometry(font, text, size) {
  const scale = size / font.unitsPerEm
  let advance = 0
  const glyphs = []
  const bounds = { left: Infinity, top: Infinity, right: -Infinity, bottom: -Infinity }
  for (const character of text) {
    const glyph = font.glyphs[character]
    assert(glyph, `Missing baked font glyph: ${JSON.stringify(character)}`)
    const [width, path, box] = glyph
    if (box) {
      bounds.left = Math.min(bounds.left, (advance + box[0]) * scale)
      bounds.right = Math.max(bounds.right, (advance + box[2]) * scale)
      bounds.top = Math.min(bounds.top, -box[3] * scale)
      bounds.bottom = Math.max(bounds.bottom, -box[1] * scale)
    }
    glyphs.push({ character, path, offset: advance })
    advance += width
  }
  return { advance: advance * scale, bounds, glyphs, scale }
}

class Card {
  constructor(fonts) {
    this.fonts = fonts
    this.decorations = []
    this.definitions = new Map()
    this.images = []
    this.textBounds = []
  }

  text(value, x, baseline, {
    size = 18, font = 'sans', fill = INK, anchor = 'start', maxWidth = WIDTH - 48,
  } = {}) {
    const text = String(value)
    const geometry = textGeometry(this.fonts[font], text, size)
    assert(geometry.advance <= maxWidth, `Text exceeds ${maxWidth}px: ${text}`)
    const left = x - (anchor === 'middle' ? geometry.advance / 2 : anchor === 'end' ? geometry.advance : 0)
    const bounds = {
      left: left + geometry.bounds.left, right: left + geometry.bounds.right,
      top: baseline + geometry.bounds.top, bottom: baseline + geometry.bounds.bottom,
    }
    assert(bounds.left >= 8 && bounds.right <= WIDTH - 8 &&
      bounds.top >= 6 && bounds.bottom <= HEIGHT - 3, `Text outside card: ${text}`)
    for (const existing of this.textBounds) {
      assert(bounds.left >= existing.right || bounds.right <= existing.left ||
        bounds.top >= existing.bottom || bounds.bottom <= existing.top,
      `Overlapping labels: ${text} / ${existing.text}`)
    }
    this.textBounds.push({ ...bounds, text })
    const paths = geometry.glyphs.map(glyph => {
      if (!glyph.path) return ''
      const id = `${font}-${glyph.character.codePointAt(0).toString(16)}`
      this.definitions.set(id, `<path id="${id}" d="${xml(glyph.path)}"/>`)
      return `<use href="#${id}" x="${glyph.offset}"/>`
    }).join('')
    this.decorations.push(
      `<g aria-label="${xml(text)}" fill="${fill}" transform="translate(${left} ${baseline}) scale(${geometry.scale} ${-geometry.scale})">${paths}</g>`,
    )
    return geometry.advance
  }

  rule(y, left = 24, right = WIDTH - 24) {
    this.decorations.push(`<path d="M${left} ${y}H${right}" stroke="${LINE}"/>`)
  }

  legend(methods, baseline) {
    const size = 20
    const widths = methods.map(method => textGeometry(this.fonts.sans, method.name, size).advance + 54)
    const gap = 30
    let left = (WIDTH - widths.reduce((sum, width) => sum + width, 0) - gap * (methods.length - 1)) / 2
    assert(left >= 24, 'Recovery legend exceeds the card width')
    methods.forEach((method, index) => {
      this.decorations.push(
        `<path d="M${left} ${baseline - 6}h40" fill="none" stroke="${method.color}" stroke-width="3" ${method.dash ? `stroke-dasharray="${method.dash}"` : ''}/>`,
      )
      this.text(method.name, left + 54, baseline, { size })
      left += widths[index] + gap
    })
  }

  image(input, left, top, width, height, blend = 'over') {
    assert(left >= 0 && top >= 0 && left + width <= WIDTH && top + height <= HEIGHT,
      'An original figure exceeds the card')
    for (const label of this.textBounds) {
      assert(label.left >= left + width || label.right <= left ||
        label.top >= top + height || label.bottom <= top,
      `Figure overlaps label: ${label.text}`)
    }
    this.images.push({ input, left, top, blend })
  }

  footer(baseline = 617, size = 16) {
    this.text(FOOTER, WIDTH / 2, baseline, { size, fill: MUTED, anchor: 'middle' })
  }

  async render() {
    const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="${WIDTH}" height="${HEIGHT}" viewBox="0 0 ${WIDTH} ${HEIGHT}">
      <defs>${[...this.definitions.values()].join('')}</defs>
      <rect width="${WIDTH}" height="${HEIGHT}" fill="${PAPER}"/>
      ${this.decorations.join('')}
    </svg>`
    const png = await sharp(Buffer.from(svg)).composite(this.images).removeAlpha()
      .png({ compressionLevel: 9, adaptiveFiltering: false, palette: false }).toBuffer()
    const metadata = await sharp(png).metadata()
    assert.equal(metadata.width, WIDTH)
    assert.equal(metadata.height, HEIGHT)
    assert.equal(metadata.format, 'png')
    assert.equal(metadata.channels, 3)
    return png
  }
}

function arxivVersion(paper) {
  return `${paper.arxivId}v${paper.version}`
}

async function measuredCells(evidence) {
  const benchmarks = BENCHMARK_IDS.map(id => {
    const benchmark = evidence.diffusionBenchmarks.find(item => item.id === id)
    assert(benchmark, `Missing measured benchmark: ${id}`)
    assert.equal(benchmark.results.length, 6, `${id}: the six-method layout needs review`)
    return benchmark
  })
  const rows = await Promise.all(['performance', 'forgetting'].map(async metric =>
    Promise.all(benchmarks.map(async benchmark => {
      const relativePath = `public/blog-assets/diffusion/results/${benchmark.id}-${metric}-paper-cell.svg`
      const source = await readFile(resolve(ROOT, relativePath), 'utf8')
      assert(source.includes('viewBox="0 0 320 200"'), `${relativePath}: unexpected canvas`)
      const description = source.match(/<dc:description>([\s\S]*?)<\/dc:description>/)?.[1]
      assert(description, `${relativePath}: missing scientific provenance`)
      const paper = evidence.diffusionPapers[benchmark.paper]
      assert(description.includes(`${paper.htmlUrl}#${benchmark.source.anchor}`),
        `${relativePath}: source differs from evidence.ts`)
      for (const result of benchmark.results) {
        const estimate = result[metric]
        const expected = estimate === null ? `${result.method}: not reported.` :
          `${result.method}: ${estimate.mean.toFixed(1)} ± ${estimate.standardError.toFixed(1)} ${benchmark.metrics[metric].unit}.`
        assert(description.includes(xml(expected)), `${relativePath}: stale estimate for ${result.method}`)
        assert.equal(source.includes(`id="bar-${result.id}"`), estimate !== null,
          `${relativePath}: missing or unexpected bar for ${result.method}`)
      }
      // Set only the in-memory viewport; the original viewBox/paths stay intact.
      // This avoids platform-dependent point/DPI conversion. Original 16.5px
      // type becomes 18.15px at 1.1 × the original 320×200 vector canvas.
      assert(source.includes('width="320pt" height="200pt"'), `${relativePath}: unexpected viewport`)
      const viewport = source.replace('width="320pt" height="200pt"', 'width="352" height="220"')
      const { data, info } = await sharp(Buffer.from(viewport))
        .png().toBuffer({ resolveWithObject: true })
      assert.equal(info.width, 352)
      assert.equal(info.height, 220)
      return { data, info }
    })),
  ))
  return { benchmarks, rows }
}

async function recoveryImages(recovery) {
  assert.deepEqual(Array.from(recovery.recoveryPanels, panel => panel.id), PANEL_IDS,
    'The original Figure 2 panel order changed; review the combined card')
  return Promise.all(recovery.recoveryPanels.map(async panel => {
    assert(panel.src.startsWith('/blog-assets/diffusion/'), `Unexpected plot path: ${panel.src}`)
    const input = await readFile(resolve(ROOT, 'public', panel.src.slice(1)))
    const metadata = await sharp(input).metadata()
    assert.equal(metadata.width, panel.width, `${panel.id}: source width changed`)
    assert.equal(metadata.height, panel.height, `${panel.id}: source height changed`)
    // Width-only resizing keeps the entire original aspect, ticks and legend.
    const { data, info } = await sharp(input).resize({ width: 1152 })
      .png().toBuffer({ resolveWithObject: true })
    assert.equal(info.height, Math.round(1152 * panel.height / panel.width))
    return { panel, data, info }
  }))
}

async function renderMeasured(fonts, evidence, cells) {
  const card = new Card(fonts)
  card.text(evidence.diffusionEvidence.title, 24, 44, { size: 34, font: 'serif' })
  card.text('Whiskers: mean ±1 SE · compare within columns', 1176, 42,
    { size: 18, anchor: 'end', fill: MUTED })
  cells.benchmarks.forEach((benchmark, column) => {
    const x = 24 + column * 400
    const center = x + 176
    const context = `${benchmark.label} · ${benchmark.taskCount} ${benchmark.id === 'trust-cw10' ? 'skills' : 'tasks'}`
    card.text(context, center, 81, { size: 24, font: 'serif', anchor: 'middle', maxWidth: 352 })
    card.text(`${benchmark.metrics.performance.label} ${benchmark.metrics.performance.direction === 'lower' ? '↓' : '↑'}`,
      center, 104, { size: 18, anchor: 'middle', maxWidth: 352 })
    card.text('Average forgetting ↓', center, 357, { size: 18, anchor: 'middle', maxWidth: 352 })
  })
  const rank = arxivVersion(evidence.diffusionPapers.rankOne)
  const trust = arxivVersion(evidence.diffusionPapers.trustRegion)
  card.text(`Sources: ImageNet-1k — arXiv:${rank}, Table 1; ImageNet-500 / CW10 — arXiv:${trust}, Table 1.`,
    WIDTH / 2, 605, { size: 18, anchor: 'middle', fill: MUTED })
  card.footer(622, 14)
  cells.rows.forEach((row, rowIndex) => row.forEach(({ data, info }, column) =>
    card.image(data, 24 + column * 400, rowIndex === 0 ? 111 : 365, info.width, info.height)))
  return card.render()
}

async function renderRecovery(fonts, evidence, images) {
  const card = new Card(fonts)
  card.text('Task 1 recovery during continual learning', 24, 44, { size: 34, font: 'serif' })
  card.text('Original Figure 2', 1176, 42, { size: 18, anchor: 'end', fill: MUTED })
  card.text('Task 1 performance across ten sequential tasks · original paper curves', 24, 70,
    { size: 18, fill: MUTED })
  images.forEach(({ panel }, index) => {
    const baseline = index === 0 ? 101 : 344
    card.text(panel.title, 24, baseline, { size: 24, font: 'serif', maxWidth: 320 })
    card.text(panel.measure, 1176, baseline - 1, { size: 18, anchor: 'end' })
  })
  card.text(`Source: Trust Region, arXiv:${arxivVersion(evidence.diffusionPapers.trustRegion)}, Fig. 2 · Gradient updates on the horizontal axes`,
    WIDTH / 2, 594, { size: 18, fill: MUTED, anchor: 'middle' })
  card.footer()
  images.forEach(({ data, info }, index) =>
    card.image(data, 24, index === 0 ? 111 : 352, info.width, info.height, 'multiply'))
  return card.render()
}

async function renderRecoveryPanel(fonts, evidence, recovery, image, index) {
  const { panel, data, info } = image
  const benchmark = evidence.diffusionBenchmarks.find(item => item.id === `trust-${panel.id}`)
  assert(benchmark, `Missing protocol for recovery panel ${panel.id}`)
  const figure = `Figure 2(${String.fromCharCode(97 + index)})`
  const card = new Card(fonts)
  card.text(`${panel.title} · Task 1 recovery`, 24, 49, { size: 34, font: 'serif' })
  card.text(figure, 1176, 46, { size: 18, anchor: 'end', fill: MUTED })
  card.text(panel.measure, 24, 84, { size: 22 })
  card.rule(107)
  card.text(`${benchmark.taskCount} sequential tasks · Task 1 evaluated throughout training`, 24, 144,
    { size: 20, fill: MUTED })
  const top = Math.round(302 - info.height / 2)
  card.text('Gradient updates · T1–T10 mark the sequential tasks', WIDTH / 2, 435,
    { size: 20, fill: MUTED, anchor: 'middle' })
  // Figure 2(b) already carries the shared legend; 2(a) has no embedded legend.
  if (panel.id === 'imagenet500') card.legend(recovery.recoveryMethods, 477)
  card.rule(507)
  card.text(`Original ${figure} · ${evidence.diffusionPapers.trustRegion.title}`,
    24, 539, { size: 18, fill: MUTED })
  card.text(`arXiv:${arxivVersion(evidence.diffusionPapers.trustRegion)} · Full source panel, with its original curves and task boundaries`,
    24, 568, { size: 18, fill: MUTED })
  card.footer()
  card.image(data, 24, top, info.width, info.height, 'multiply')
  return card.render()
}

async function main() {
  const [evidence, recovery, fonts] = await Promise.all([
    loadData('src/blog/diffusion/evidence.ts'),
    loadData('src/blog/diffusion/recovery-data.ts'),
    loadFonts(),
  ])
  const [cells, images] = await Promise.all([measuredCells(evidence), recoveryImages(recovery)])
  const cards = await Promise.all([
    renderMeasured(fonts, evidence, cells).then(data => ['measured-results', data]),
    renderRecovery(fonts, evidence, images).then(data => ['recovery', data]),
    ...images.map((image, index) => renderRecoveryPanel(fonts, evidence, recovery, image, index)
      .then(data => [`recovery-${image.panel.id}`, data])),
  ])
  // All source, typography, layout and output checks pass before touching outputs.
  await mkdir(OUTPUT, { recursive: true })
  for (const [name, data] of cards) {
    await writeFile(resolve(OUTPUT, `${name}.png`), data)
    console.log(`${name}.png: ${WIDTH}×${HEIGHT}, ${data.length.toLocaleString('en-US')} bytes`)
  }
  console.log('Verified 35 reported estimates, one unreported value, and two complete original curve panels.')
}

await main()
